function processComments(comments) {
  if (!Array.isArray(comments)) {
    console.error("警告：comments 不是数组！实际值为：", comments);
    return [];
  }

  return comments.map(comment => {
    return {
      author_id: comment.author_id,
      //ispublic: comment.public,
      body: comment.body
    };
  });
}

const inputData = $input.first().json;
const processedData = processComments(inputData.comments);

// 直接返回处理后的数组，不添加额外包装
return processedData;

function maskSensitiveInfo(inputText) {
  if (!inputText || typeof inputText !== 'string') return inputText;

  // 步骤1：按单词分割文本（保留空格和标点）
  const words = inputText.split(/(\s+|\W+)/); // 正则分割保留分隔符
  const maskedWords = words.map(word => {
    // 跳过非单词字符（如空格、标点）
    if (!/\w/.test(word)) return word;

    // 步骤2：检查单词中数字总数 ≥5
    const digitCount = (word.match(/\d/g) || []).length;
    if (digitCount < 5) return word;

    // 步骤3：替换单词中的所有数字为 *
    return word.replace(/\d/g, '*');
  });

  return maskedWords.join('');
}

// Safely get the first item from the 'Loop Over each comment' node
const item = $('Loop Over each comment').first();

// Check if the item and the required 'body' property exist before processing
if (item && item.json && item.json.body) {
  const res = maskSensitiveInfo(item.json.body);

  return [{
    result: res
  }];
}

// If no item or body is found, return an empty array.
// This tells n8n to stop this execution path without an error.
return [];

const rawEmail = $('HTTP Request').first()?.json?.user.email || '未找到邮箱';
let body = $input.first()?.json?.result || '未找到内容';
//let time = $('AI_Filter').first().json.created_at;
//let createTime= "Created At"

// 移除所有换行符（兼容Windows/Unix/Mac系统）
body = body.replace(/(\r\n|\n|\r)/gm, ' '); // [2,5](@ref)

// 处理邮箱格式
let processedEmail;
if (rawEmail.endsWith('@agora.io')) {
    processedEmail = 'agent'; 
} else {
    processedEmail = 'Customer';
}

// 返回{邮箱: 内容}格式的对象
return { 
    //[createTime]:time,
    [processedEmail]: body    
};

function cleanInput(input) {
    // 1. 提取最内层有效数组（input[0].data）
    const dataArray =input;

    // 2. 过滤空对象：保留至少包含一个有效键值对的对象
    const filteredArray = dataArray.filter(item => {
        return Object.keys(item).length > 0; // 仅保留非空对象[6,8](@ref)
    });

    return filteredArray;
}

// 示例调用

const result = cleanInput($input.first().json.data);
return {result}
